      background: linear-gradient(180deg, rgba(255,255,255,.07), rgba(255,255,255,.04));
      box-shadow: var(--shadow);
    }

    .hero-main{
      padding: 26px 26px 24px;
      overflow: hidden;
      position: relative;
    }
    .hero-main:before{
      content:"";
      position:absolute;
      inset:-2px;
      background:
        radial-gradient(600px 240px at 15% 15%, rgba(255,176,0,.25), transparent 55%),
        radial-gradient(600px 240px at 90% 25%, rgba(0,212,255,.18), transparent 55%);
      pointer-events:none;
    }
    .hero-main > *{ position: relative; z-index: 1; }

    .badge{
      display: inline-flex;
      gap: 10px;
      align-items: center;
      padding: 8px 12px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: rgba(255,255,255,.05);
      color: var(--muted);
      font-size: 13px;
      width: fit-content;
    }
    .dot{
      width: 9px; height: 9px;
      border-radius: 50%;
      background: var(--accent2);
      box-shadow: 0 0 0 4px rgba(0,212,255,.15);
    }

    h1{
      margin: 14px 0 10px;
      font-size: clamp(30px, 4.1vw, 46px);
      line-height: 1.06;
      letter-spacing: -0.6px;
    }
    .lead{
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 15.5px;
      line-height: 1.6;
      max-width: 60ch;
    }

    .hero-cta{
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 10px;
    }

    .mini-stats{
      margin-top: 18px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
    }
    .stat{
      padding: 12px 12px;
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,.10);
      background: rgba(0,0,0,.18);
    }
    .stat b{ display:block; font-size: 18px; }
    .stat span{ color: var(--muted); font-size: 12.5px; }

    /* Right column: highlights */
    .hero-side{
      padding: 18px;
      display: grid;
      grid-template-rows: auto 1fr;
      gap: 12px;
    }
    .side-title{
      display:flex;
      align-items:center;
      justify-content: space-between;
      gap: 12px;
      padding: 8px 4px 0;
    }
    .side-title h2{
      margin: 0;
      font-size: 15px;
      color: rgba(234,240,255,.92);
      letter-spacing: .2px;
    }
    .pill{
      font-size: 12px;
      color: var(--muted);
      border: 1px solid var(--border);
      background: rgba(255,255,255,.05);
      padding: 6px 10px;
      border-radius: 999px;
    }

    .highlight{
      border-radius: 16px;
      border: 1px solid rgba(255,255,255,.12);
      background: rgba(255,255,255,.05);
      overflow: hidden;
      position: relative;
      display: grid;
      grid-template-rows: auto auto;
    }

    .highlight .thumb{
      aspect-ratio: 16/9;
      background:
        radial-gradient(400px 260px at 30% 40%, rgba(255,176,0,.28), transparent 60%),
        radial-gradient(500px 280px at 70% 20%, rgba(0,212,255,.18), transparent 60%),
        linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,0));
      border-bottom: 1px solid rgba(255,255,255,.12);
      position: relative;
    }
    .play{
      position: absolute;
      left: 14px; bottom: 14px;
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 10px 12px;
      border-radius: 999px;
      border: 1px solid rgba(255,255,255,.18);
      background: rgba(0,0,0,.25);
      font-weight: 700;
      font-size: 13px;
    }
    .play i{
      width: 26px; height: 26px;
      border-radius: 50%;
      background: linear-gradient(135deg, rgba(255,176,0,.95), rgba(255,176,0,.65));
      display: inline-flex;
      align-items: center;
      justify-content: center;
      color: #111;
      font-style: normal;
      font-weight: 900;
      padding-left: 2px;
    }

    .highlight .meta{
      padding: 12px 14px 14px;
    }
    .highlight .meta b{ display:block; margin-bottom: 6px; }
    .highlight .meta p{
      margin: 0;
      color: var(--muted);
      font-size: 13.5px;
      line-height: 1.5;
    }

    /* Sections */
    section{ padding: 28px 0; }
    .section-head{
      display:flex;
      align-items: end;
      justify-content: space-between;
      gap: 14px;
      margin-bottom: 14px;
    }
    .section-head h2{
      margin: 0;
      font-size: 20px;
      letter-spacing: .2px;
    }
    .section-head p{
      margin: 0;
      color: var(--muted);
      font-size: 13.5px;
      max-width: 65ch;
    }

    .grid-3{
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }

    .tile{
      padding: 16px;
      border-radius: var(--radius);
      border: 1px solid var(--border);
      background: rgba(255,255,255,.05);
      box-shadow: 0 10px 30px rgba(0,0,0,.22);
    }
    .tile h3{ margin: 0 0 8px; font-size: 16px; }
    .tile p{ margin: 0; color: var(--muted); line-height: 1.6; font-size: 13.8px; }
    .tagrow{ display:flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
    .tag{
      font-size: 12px;
      color: rgba(234,240,255,.8);
      border: 1px solid rgba(255,255,255,.14);
      background: rgba(0,0,0,.16);
      padding: 6px 10px;
      border-radius: 999px;
    }

    /* News list */
    .news{
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: 12px;
      align-items: start;
    }

    .news-main{
      padding: 18px;
    }
    .news-item{
      display: grid;
      grid-template-columns: 90px 1fr;
      gap: 12px;
      padding: 12px;
      border-radius: 16px;
      border: 1px solid rgba(255,255,255,.10);
      background: rgba(0,0,0,.15);
    }
    .news-item + .news-item{ margin-top: 10px; }
    .thumb2{
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,.12);
      background:
        radial-gradient(220px 120px at 30% 40%, rgba(0,212,255,.20), transparent 60%),
        radial-gradient(220px 120px at 70% 10%, rgba(255,176,0,.22), transparent 60%),
        rgba(255,255,255,.05);
      aspect-ratio: 1/1;
    }
    .news-item b{ display:block; margin-bottom: 6px; }
    .news-item p{ margin: 0; color: var(--muted); font-size: 13.5px; line-height: 1.5; }
    .meta-row{
      display:flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 8px;
      color: rgba(234,240,255,.62);
      font-size: 12px;
    }

    .news-side{
      padding: 18px;
    }
    .sidebox{
      padding: 14px;
      border-radius: 16px;
      border: 1px solid rgba(255,255,255,.10);
      background: rgba(0,0,0,.14);
    }
    .sidebox + .sidebox{ margin-top: 10px; }
    .sidebox h3{ margin: 0 0 6px; font-size: 14.5px; }
    .sidebox p{ margin: 0; color: var(--muted); font-size: 13.5px; line-height: 1.55; }

    /* Gallery */
    .gallery{
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 12px;
    }
    .shot{
      grid-column: span 4;
      border-radius: var(--radius);
      border: 1px solid rgba(255,255,255,.12);
      background:
        radial-gradient(420px 240px at 30% 40%, rgba(255,176,0,.22), transparent 60%),
        radial-gradient(420px 240px at 75% 20%, rgba(0,212,255,.18), transparent 60%),
        rgba(255,255,255,.05);
      aspect-ratio: 16/10;
      position: relative;
      overflow: hidden;
    }
    .shot:after{
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 55%, rgba(0,0,0,.35));
    }
    .shot span{
      position: absolute;
      left: 14px;
      bottom: 12px;
      z-index: 2;
      font-weight: 750;
      font-size: 13px;
      letter-spacing: .2px;
    }
    .shot.wide{ grid-column: span 8; }

    /* Contact */
    .contact{
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      align-items: start;
    }
    form{
      padding: 18px;
    }
    label{
      display:block;
      font-size: 13px;
      color: rgba(234,240,255,.8);
      margin: 12px 0 7px;
    }
    input, textarea{
      width: 100%;
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,.14);
      background: rgba(0,0,0,.22);
      color: var(--text);
      padding: 12px 12px;
      outline: none;
      transition: .15s ease;
      font-size: 14px;
    }
    input:focus, textarea:focus{
      border-color: rgba(0,212,255,.35);
      box-shadow: 0 0 0 4px rgba(0,212,255,.10);
    }
    textarea{ min-height: 120px; resize: vertical; }
    .form-row{ display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }

    .contact-info{
      padding: 18px;
    }
    .contact-info h3{ margin: 0 0 8px; }
    .contact-info p{ margin: 0 0 12px; color: var(--muted); line-height: 1.6; }
    .kvs{
      display:grid; gap: 10px;
      margin-top: 10px;
    }
    .kv{
      display:flex; justify-content: space-between; gap: 10px;
      padding: 12px;
      border-radius: 14px;
      border: 1px solid rgba(255,255,255,.10);
      background: rgba(0,0,0,.14);
      font-size: 13.5px;
    }
    .kv span{ color: var(--muted); }

    /* Footer */
    footer{
      padding: 26px 0 34px;
      border-top: 1px solid var(--border);
      background: rgba(0,0,0,.18);
      margin-top: 10px;
    }
    .foot{
      display:flex;
      align-items: start;
      justify-content: space-between;
      gap: 14px;
      flex-wrap: wrap;
    }
    .fine{
      color: rgba(234,240,255,.58);
      font-size: 12.5px;
      line-height: 1.6;
      max-width: 72ch;
    }
    .footlinks{
      display:flex; gap: 10px; flex-wrap: wrap;
    }
    .footlinks a{
      color: rgba(234,240,255,.7);
      font-size: 13px;
      border: 1px solid rgba(255,255,255,.12);
      background: rgba(255,255,255,.04);
      padding: 8px 10px;
      border-radius: 999px;
    }

    /* Mobile */
    @media (max-width: 920px){
      .hero-grid{ grid-template-columns: 1fr; }
      .news{ grid-template-columns: 1fr; }
      .grid-3{ grid-template-columns: 1fr; }
      .contact{ grid-template-columns: 1fr; }
      .form-row{ grid-template-columns: 1fr; }
      .gallery .shot{ grid-column: span 6; }
      .gallery .shot.wide{ grid-column: span 12; }
    }

    @media (max-width: 720px){
      .navlinks{ display: none; }
      .hamburger{ display: inline-flex; }
      .actions .btn.primary{ display:none; } /* keep header compact */
      .mobile-menu{
        display: none;
        padding: 0 0 14px;
      }
      .mobile-menu.open{ display:block; }
      .mobile-menu a{
        display:block;
        padding: 12px 14px;
        margin-top: 8px;
        border-radius: 14px;
        border: 1px solid rgba(255,255,255,.12);
        background: rgba(255,255,255,.04);
        color: rgba(234,240,255,.88);
      }
    }
  </style>
</head>

